@TestSetup static void captureSeed(){Map<String,Object> r=new Map<String,Object>();try{
r.put('value',new NullPointerException().getStackTraceString());r.put('completed',true);
}catch(Exception captureException){r.put('exceptionType',captureException.getTypeName());r.put('exceptionMessage',captureException.getMessage());r.put('stack',captureException.getStackTraceString());}String capturePayload=JSON.serialize(r);if(capturePayload.length()>32000){capturePayload=JSON.serialize(new Map<String,Object>{'captureTransportError'=>'test-setup-payload-overflow','rawCharacters'=>capturePayload.length()});}insert new Account(Name='E51_PAYLOAD',Description=capturePayload);}
@IsTest static void testPart00(){List<Account> transportRows=[SELECT Description FROM Account WHERE Name='E51_PAYLOAD' LIMIT 2];String captureJson=transportRows.size()==1?transportRows[0].Description:JSON.serialize(new Map<String,Object>{'fixtureError'=>'transport-row-count','rowCount'=>transportRows.size()});String rawHash=EncodingUtil.convertToHex(Crypto.generateDigest('SHA-256',Blob.valueOf(captureJson)));String encodedPayload=EncodingUtil.base64Encode(Blob.valueOf(captureJson));if(encodedPayload.length()>7680){System.assert(false,'C126_RESULT|C03-05|'+JSON.serialize(new Map<String,Object>{'transportError'=>'assertion-chunks-overflow','encodedLength'=>encodedPayload.length(),'maximumEncodedLength'=>7680}));}Integer offset=0;String resultChunk=encodedPayload.length()>offset?encodedPayload.substring(offset,Math.min(offset+320,encodedPayload.length())):'';String envelope='C126_RESULT|C03-05|'+JSON.serialize(new Map<String,Object>{'chunk'=>resultChunk,'hash'=>rawHash,'total'=>24,'part'=>0});System.assert(envelope.length()+42<=620,'C126_TRANSPORT_ERROR|assertion-envelope-overflow');System.assert(false,envelope);}
