@IsTest private class E51C0301Test{
@TestSetup static void captureSeed(){Map<String,Object> r=new Map<String,Object>();try{
r.put('value',C51A68TraceEmitter.constructed());r.put('completed',true);
}catch(Exception captureException){r.put('exceptionType',captureException.getTypeName());r.put('exceptionMessage',captureException.getMessage());r.put('stack',captureException.getStackTraceString());}String capturePayload=JSON.serialize(r);if(capturePayload.length()>32000){capturePayload=JSON.serialize(new Map<String,Object>{'captureTransportError'=>'test-setup-payload-overflow','rawCharacters'=>capturePayload.length()});}insert new Account(Name='E51_PAYLOAD',Description=capturePayload);}
