Map<String,Object> r=new Map<String,Object>();try{r.put('value',C51A68TraceEmitter.thrown());r.put('completed',true);}catch(Exception fault){r.put('exceptionType',fault.getTypeName());r.put('exceptionMessage',fault.getMessage());}String captureJson=JSON.serialize(r);if(captureJson.length()>552){captureJson=JSON.serialize(new Map<String,Object>{'captureTransportError'=>'payload-too-long','length'=>captureJson.length()});}System.assert(false,'C126_RESULT|C03-02-METHOD|'+captureJson);
